Definition dusc_segA_post (sp gp tp t0 t1 t2 a6 a7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r K ctx own first lo shi : Z) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 a4 a5 m' j16 j7,
    ms' = MS (mkR (Z_to_bv 64 P_A_DUSC_RET) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2
                  (Z_to_bv 64 (r + 56)) (Z_to_bv 64 K) (Z_to_bv 64 ctx) (Z_to_bv 64 own) a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (K + 8)) (Z_to_bv 64 0) (Z_to_bv 64 P_A_CREATE_SSVC) (Z_to_bv 64 own) (Z_to_bv 64 r) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (Z.shiftr (r + 56) 3 + 2147450880)) s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CREATE_SSVC) fc None m' (seg_rom bsegs)
    /\ munch (adusf_W lo sp r) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -112)
    /\ rw_cells bsegs m' (bv_unsigned sp + -112) (dus_frame0 r 0 j16 j7 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
