  ro_cells bsegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ati_ok m kti kname) ->
  ASvcChain m first L -> find_svc kti kid kname L = 0 ->
  Forall (fun e => se_addr e + 48 <= r \/ r + SZ_REG <= se_addr e) L ->
  bv_unsigned sp <= K -> K + 16 <= shi -> K mod 8 = 0 ->
  0 < ctx < 2^64 -> ctx mod 8 = 0 -> 0 <= own < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ADUS_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp mod 16 = 0 ->
  evt bsegs (dusc_segA_post sp gp tp t0 t1 t2 a6 a7 s10 s11 t3 t4 t5 t6 F fc LB r K ctx own first lo shi ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) (wz K) (wz P_A_CREATE_SSVC) (wz own) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_DO_USE_SERVICE) fc None m (seg_rom bsegs)).
